-- FS-UX-007: evidence-based delivery and installation tracking. No external execution.
begin;
alter table public.furnishing_installation_projects add column if not exists source_readiness_snapshot_id uuid references public.fsux6_readiness_snapshots(id),add column if not exists tracking_status text not null default 'draft' check(tracking_status in('draft','awaiting_order_evidence','in_fulfillment','delivery_in_progress','installation_in_progress','needs_attention','awaiting_inspection','complete','archived')),add column if not exists current_tracking_version bigint not null default 1,add column if not exists responsible_operator_id uuid references public.profiles(id),add column if not exists archived_at timestamptz;
create unique index fsux7_source_snapshot_once on public.furnishing_installation_projects(source_readiness_snapshot_id)where source_readiness_snapshot_id is not null;
create index fsux7_installation_library on public.furnishing_installation_projects(workspace_id,tracking_status,updated_at desc)where archived_at is null;

create table public.fsux7_planned_lines(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),procurement_line_id uuid not null references public.furnishing_procurement_lines(id),source_selection_id uuid not null references public.furnishing_product_selections(id),room_id uuid not null references public.furnishing_rooms(id),product_id uuid not null references public.furnishing_products(id),product_version_id uuid not null references public.furnishing_product_versions(id),retailer_id uuid references public.furnishing_retailers(id),sku text,variant text,planned_quantity numeric(12,4) not null check(planned_quantity>0),priority text not null check(priority in('essential','recommended','optional')),fulfillment_required boolean not null,assembly_required boolean not null default false,installation_required boolean not null default false,baseline jsonb not null,baseline_digest text not null,created_at timestamptz not null default now(),unique(installation_project_id,procurement_line_id));
create table public.fsux7_order_evidence(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),procurement_order_id uuid not null unique references public.furnishing_procurement_orders(id),evidence_class text not null check(evidence_class in('manually_recorded','customer_reported','operator_verified','document_verified','provider_confirmed','controlled_test')),verification_state text not null check(verification_state in('reported_unverified','verified','disputed','superseded')),ordering_party text not null,recording_actor uuid not null references public.profiles(id),verification_actor uuid references public.profiles(id),evidence_reference text,correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,idempotency_key));
create table public.fsux7_order_allocations(id uuid primary key default gen_random_uuid(),order_evidence_id uuid not null references public.fsux7_order_evidence(id),order_line_id uuid not null references public.furnishing_procurement_order_lines(id),planned_line_id uuid not null references public.fsux7_planned_lines(id),room_id uuid not null references public.furnishing_rooms(id),ordered_quantity numeric(12,4) not null check(ordered_quantity>0),intentionally_not_ordered_quantity numeric(12,4) not null default 0 check(intentionally_not_ordered_quantity>=0),reason text,actor_id uuid not null references public.profiles(id),correlation_id text not null,created_at timestamptz not null default now(),unique(order_line_id,planned_line_id));
alter table public.furnishing_procurement_orders add column if not exists installation_project_id uuid references public.furnishing_installation_projects(id),add column if not exists evidence_class text check(evidence_class is null or evidence_class in('manually_recorded','customer_reported','operator_verified','document_verified','provider_confirmed','controlled_test')),add column if not exists verification_state text check(verification_state is null or verification_state in('reported_unverified','verified','disputed','superseded')),add column if not exists recording_actor_id uuid references public.profiles(id),add column if not exists ordering_party text,add column if not exists archived_at timestamptz;
create unique index fsux7_external_order_reference on public.furnishing_procurement_orders(installation_project_id,retailer_id,po_number)where installation_project_id is not null and archived_at is null;
alter table public.furnishing_shipments add column if not exists installation_project_id uuid references public.furnishing_installation_projects(id),add column if not exists evidence_class text check(evidence_class is null or evidence_class in('manually_recorded','customer_reported','operator_verified','document_verified','provider_confirmed','controlled_test')),add column if not exists verification_state text check(verification_state is null or verification_state in('reported_unverified','verified','disputed')),add column if not exists correlation_id text,add column if not exists idempotency_key text,add column if not exists archived_at timestamptz;
create unique index fsux7_shipment_replay on public.furnishing_shipments(installation_project_id,idempotency_key)where installation_project_id is not null;
create unique index fsux7_shipment_reference on public.furnishing_shipments(order_id,carrier,tracking_number)where tracking_number is not null and archived_at is null;
create table public.fsux7_delivery_events(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),shipment_id uuid not null references public.furnishing_shipments(id),state text not null check(state in('expected','carrier_reported_delivered','received','partially_received','received_with_exception','not_found','refused','returned_to_sender')),evidence_class text not null check(evidence_class in('manually_recorded','customer_reported','operator_verified','document_verified','provider_confirmed','controlled_test')),event_at timestamptz not null,receiving_person text,delivery_location text,condition_summary text,evidence jsonb not null default '{}',recording_actor uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,idempotency_key));
alter table public.furnishing_procurement_receipts add column if not exists installation_project_id uuid references public.furnishing_installation_projects(id),add column if not exists delivery_event_id uuid references public.fsux7_delivery_events(id),add column if not exists evidence_class text check(evidence_class is null or evidence_class in('manually_recorded','customer_reported','operator_verified','document_verified','provider_confirmed','controlled_test')),add column if not exists correlation_id text,add column if not exists archived_at timestamptz;
create table public.fsux7_inventory_units(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),planned_line_id uuid not null references public.fsux7_planned_lines(id),order_line_id uuid references public.furnishing_procurement_order_lines(id),shipment_id uuid references public.furnishing_shipments(id),receipt_line_id uuid references public.furnishing_procurement_receipt_lines(id),unit_identity text not null,serial_number text,current_location text not null default 'property_staging' check(current_location in('property_staging','room','off_site_storage','return_holding','exception_holding','unknown')),room_id uuid references public.furnishing_rooms(id),condition text not null default 'uninspected',assembly_state text not null default 'not_ready' check(assembly_state in('not_required','required','not_ready','ready','in_progress','completed','completed_with_issue','failed','rework_required')),installation_state text not null default 'not_ready' check(installation_state in('not_required','not_ready','ready','planned','in_progress','installed','installed_with_exception','inspection_required','rework_required','accepted')),inspection_state text not null default 'pending' check(inspection_state in('pending','passed','failed','accepted_with_warning')),created_at timestamptz not null default now(),unique(installation_project_id,unit_identity));
create table public.fsux7_room_allocations(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),planned_line_id uuid not null references public.fsux7_planned_lines(id),receipt_line_id uuid not null references public.furnishing_procurement_receipt_lines(id),unit_id uuid references public.fsux7_inventory_units(id),source_room_id uuid not null references public.furnishing_rooms(id),destination_room_id uuid references public.furnishing_rooms(id),location text not null,quantity numeric(12,4) not null check(quantity>0),actor_id uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,idempotency_key));
create table public.fsux7_installation_events(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),planned_line_id uuid not null references public.fsux7_planned_lines(id),unit_id uuid references public.fsux7_inventory_units(id),room_id uuid not null references public.furnishing_rooms(id),event_type text not null check(event_type in('assembly_started','assembly_completed','assembly_issue','installation_planned','installation_started','installed','installation_issue','rework_required','accepted')),quantity numeric(12,4) not null check(quantity>0),installer_description text,evidence_class text not null,evidence jsonb not null default '{}',recording_actor uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,idempotency_key));
create table public.fsux7_tracking_exceptions(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),category text not null,severity text not null check(severity in('blocking','warning','informational')),planned_line_id uuid references public.fsux7_planned_lines(id),order_id uuid references public.furnishing_procurement_orders(id),shipment_id uuid references public.furnishing_shipments(id),room_id uuid references public.furnishing_rooms(id),unit_id uuid references public.fsux7_inventory_units(id),description text not null,required_resolution text not null,status text not null default 'open' check(status in('open','resolved')),evidence jsonb not null default '{}',owner_id uuid references public.profiles(id),created_at timestamptz not null default now(),resolved_by uuid references public.profiles(id),resolved_at timestamptz,resolution_evidence jsonb);
create table public.fsux7_return_replacement_evidence(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),planned_line_id uuid not null references public.fsux7_planned_lines(id),order_id uuid not null references public.furnishing_procurement_orders(id),state text not null check(state in('return_recommended','return_requested_externally','return_authorized_externally','in_return_transit','retailer_received','refund_reported','replacement_reported','replacement_shipped','replacement_received','resolved')),quantity numeric(12,4) not null check(quantity>0),external_reference text,evidence_class text not null,evidence jsonb not null,recording_actor uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,idempotency_key));
create table public.fsux7_inspections(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),room_id uuid references public.furnishing_rooms(id),inspection_type text not null check(inspection_type in('item','room','property')),template_version text not null,result text not null check(result in('passed','failed','accepted_with_warnings')),checks jsonb not null,evidence jsonb not null,external_inspector text,recording_actor uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,idempotency_key));
create table public.fsux7_evidence_corrections(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),source_type text not null,source_id uuid not null,original_evidence jsonb not null,corrected_evidence jsonb not null,reason text not null,material boolean not null,actor_id uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,idempotency_key));
create table public.fsux7_completion_snapshots(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),tracking_version bigint not null,snapshot jsonb not null,snapshot_digest text not null,approved_by uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(installation_project_id,tracking_version),unique(installation_project_id,idempotency_key));
alter table public.fsux7_inspections add column planned_line_id uuid references public.fsux7_planned_lines(id),add column quantity numeric(12,4) check(quantity is null or quantity>0);
alter table public.fsux7_completion_snapshots add column superseded_at timestamptz,add column superseded_by_correction_id uuid;
create table public.fsux7_completion_supersessions(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),completion_snapshot_id uuid not null unique references public.fsux7_completion_snapshots(id),correction_id uuid not null references public.fsux7_evidence_corrections(id),created_at timestamptz not null default now());
create table public.fsux7_project_assignments(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),profile_id uuid not null references public.profiles(id),assignment_role text not null check(assignment_role in('delivery_operator','installer','inspector','completion_reviewer')),assigned_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),revoked_at timestamptz,unique(installation_project_id,profile_id,assignment_role));
create function public.fsux7_assert_action(i uuid,action text)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare a uuid:=auth.uid();p public.furnishing_installation_projects;workspace_role text;assigned text[];begin if a is null then raise exception 'INSTALLATION_TRACKING_ACCESS_DENIED' using errcode='42501';end if;select * into p from public.furnishing_installation_projects where id=i;if not found then raise exception 'INSTALLATION_TRACKING_NOT_FOUND';end if;workspace_role:=public.active_workspace_role(p.workspace_id);select array_agg(x.assignment_role)into assigned from public.fsux7_project_assignments x where x.installation_project_id=i and x.profile_id=a and x.revoked_at is null;if public.is_admin()or workspace_role in('owner','administrator')then null;elsif action in('record_order','record_shipment','record_delivery','record_receipt','room_allocation','resolve_exception')and(workspace_role='operator'or'delivery_operator'=any(coalesce(assigned,'{}')))then null;elsif action in('assembly','installation')and'installer'=any(coalesce(assigned,'{}'))then null;elsif action='inspection'and'inspector'=any(coalesce(assigned,'{}'))then null;elsif action='approve_completion'and'completion_reviewer'=any(coalesce(assigned,'{}'))then null;elsif action='correct_evidence'and workspace_role in('owner','administrator')then null;else raise exception 'INSTALLATION_TRACKING_ACCESS_DENIED' using errcode='42501';end if;perform public.assert_fs008g_procurement_mutation_enabled();return a;end$$;

create function public.fsux7_guard_project_open()returns trigger language plpgsql set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;begin select * into p from public.furnishing_installation_projects where id=new.installation_project_id for key share;if not found or p.archived_at is not null then raise exception 'INSTALLATION_PROJECT_ARCHIVED';end if;return new;end$$;

create function public.fsux7_assert_actor(i uuid,reviewer boolean default false)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare a uuid:=auth.uid();p public.furnishing_installation_projects;r text;begin if a is null then raise exception 'INSTALLATION_TRACKING_ACCESS_DENIED' using errcode='42501';end if;select * into p from public.furnishing_installation_projects where id=i;if not found then raise exception 'INSTALLATION_TRACKING_NOT_FOUND';end if;r:=public.active_workspace_role(p.workspace_id);if not(public.is_admin()or r in('owner','administrator','operator'))or(reviewer and not(public.is_admin()or r in('owner','administrator')))then raise exception 'INSTALLATION_TRACKING_ACCESS_DENIED' using errcode='42501';end if;perform public.assert_fs008g_procurement_mutation_enabled();return a;end$$;
create function public.fsux7_create_project(snapshot uuid,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$declare s public.fsux6_readiness_snapshots;b public.furnishing_procurement_baselines;existing public.furnishing_installation_projects;iid uuid;a uuid;line_count int;begin if auth.uid()is null then raise exception 'INSTALLATION_TRACKING_ACCESS_DENIED' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(snapshot::text,0));select * into s from public.fsux6_readiness_snapshots where fsux6_readiness_snapshots.id=fsux7_create_project.snapshot;select * into b from public.furnishing_procurement_baselines where id=s.baseline_id and archived_at is null;if not found then raise exception 'INSTALLATION_SOURCE_NOT_APPROVED';end if;select * into existing from public.furnishing_installation_projects where source_readiness_snapshot_id=s.id;if found then return jsonb_build_object('installation_project_id',existing.id,'idempotent',true,'orders_created',0,'shipments_created',0);end if;insert into public.furnishing_installation_projects(workspace_id,property_id,project_id,procurement_baseline_id,status,tracking_status,timezone,source_snapshot,source_hash,idempotency_key,created_by,responsible_operator_id,source_readiness_snapshot_id)values(b.workspace_id,b.property_id,b.project_id,b.id,'planning','awaiting_order_evidence','America/Chicago',s.snapshot,s.snapshot_digest,idempotency,auth.uid(),auth.uid(),s.id)returning id into iid;a:=public.fsux7_assert_actor(iid);insert into public.fsux7_planned_lines(installation_project_id,procurement_line_id,source_selection_id,room_id,product_id,product_version_id,retailer_id,sku,variant,planned_quantity,priority,fulfillment_required,assembly_required,installation_required,baseline,baseline_digest)select iid,l.id,l.source_plan_line_id,l.room_id,l.product_id,l.product_version_id,l.retailer_id,l.retailer_sku,l.variant,l.planned_quantity,l.priority,l.fulfillment_required,l.assembly_minor>0,l.installation_minor>0,to_jsonb(l),encode(digest(to_jsonb(l)::text,'sha256'),'hex')from public.furnishing_procurement_lines l where l.readiness_version_id=s.readiness_version_id and l.archived_at is null;get diagnostics line_count=row_count;if line_count=0 then raise exception 'INSTALLATION_SOURCE_HAS_NO_LINES';end if;return jsonb_build_object('installation_project_id',iid,'planned_lines',line_count,'idempotent',false,'orders_created',0,'shipments_created',0,'external_effects',false);end$$;
create function public.fsux7_record_order(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;o public.furnishing_procurement_orders;e public.fsux7_order_evidence;retailer uuid;planned uuid;qty numeric;ol uuid;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'record_order');select * into e from public.fsux7_order_evidence where installation_project_id=i and idempotency_key=idempotency;if found then return jsonb_build_object('order_evidence_id',e.id,'idempotent',true);end if;retailer:=(input->>'retailer_id')::uuid;planned:=(input->>'planned_line_id')::uuid;qty:=(input->>'quantity')::numeric;if qty<=0 or input->>'external_order_number' is null or input->>'ordering_party' is null then raise exception 'ORDER_EVIDENCE_INVALID';end if;insert into public.furnishing_procurement_orders(project_id,baseline_id,workspace_id,retailer_id,po_number,vendor,status,items,total,order_date,installation_project_id,evidence_class,verification_state,recording_actor_id,ordering_party)select p.project_id,p.procurement_baseline_id,p.workspace_id,retailer,input->>'external_order_number',coalesce(r.name,'Recorded retailer'),'ordered','[]',coalesce((input->>'order_total_minor')::numeric,0)/100,(input->>'order_date')::date,i,input->>'evidence_class',case when input->>'evidence_class' in('operator_verified','document_verified','provider_confirmed','controlled_test')then'verified'else'reported_unverified'end,a,input->>'ordering_party' from public.furnishing_retailers r where r.id=retailer returning * into o;insert into public.fsux7_order_evidence(installation_project_id,procurement_order_id,evidence_class,verification_state,ordering_party,recording_actor,evidence_reference,correlation_id,idempotency_key)values(i,o.id,o.evidence_class,o.verification_state,o.ordering_party,a,input->>'evidence_reference',correlation,idempotency)returning * into e;insert into public.furnishing_procurement_order_lines(order_id,procurement_line_id,snapshot,ordered_quantity,unit_price_minor,line_total_minor,currency)select o.id,l.procurement_line_id,jsonb_build_object('evidenceClass',o.evidence_class),qty,coalesce((input->>'unit_price_minor')::bigint,0),coalesce((input->>'unit_price_minor')::bigint,0)*qty,coalesce(input->>'currency','USD')from public.fsux7_planned_lines l where l.id=planned and l.installation_project_id=i returning id into ol;if ol is null then raise exception 'ORDER_ALLOCATION_SOURCE_INVALID';end if;insert into public.fsux7_order_allocations(order_evidence_id,order_line_id,planned_line_id,room_id,ordered_quantity,actor_id,correlation_id)select e.id,ol,l.id,l.room_id,qty,a,correlation from public.fsux7_planned_lines l where l.id=planned;update public.furnishing_installation_projects set tracking_status='in_fulfillment',current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;return jsonb_build_object('order_evidence_id',e.id,'order_id',o.id,'idempotent',false,'external_effects',false);end$$;
create function public.fsux7_record_receipt(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;order_line uuid;planned uuid;qty numeric;ordered numeric;received numeric;r uuid;rl uuid;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'record_receipt');if exists(select 1 from public.furnishing_procurement_receipts where installation_project_id=i and idempotency_key=idempotency)then select id into r from public.furnishing_procurement_receipts where installation_project_id=i and idempotency_key=idempotency;return jsonb_build_object('receipt_id',r,'idempotent',true);end if;order_line:=(input->>'order_line_id')::uuid;qty:=(input->>'quantity')::numeric;select ordered_quantity,procurement_line_id into ordered,planned from public.furnishing_procurement_order_lines where id=order_line for update;select coalesce(sum(x.quantity),0)into received from public.furnishing_procurement_receipt_lines x where x.procurement_line_id=planned;if qty<=0 or received+qty>ordered then raise exception 'RECEIPT_QUANTITY_EXCEEDED';end if;insert into public.furnishing_procurement_receipts(baseline_id,status,evidence,received_by,idempotency_key,installation_project_id,evidence_class,correlation_id)values(p.procurement_baseline_id,case when received+qty=ordered then'complete'else'partial'end,input,a,idempotency,i,input->>'evidence_class',correlation)returning id into r;insert into public.furnishing_procurement_receipt_lines(receipt_id,procurement_line_id,quantity,disposition,evidence)values(r,planned,qty,coalesce(input->>'disposition','accepted'),input)returning id into rl;update public.furnishing_installation_projects set tracking_status='delivery_in_progress',current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;return jsonb_build_object('receipt_id',r,'receipt_line_id',rl,'idempotent',false);end$$;
create function public.fsux7_record_installation(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;planned uuid;qty numeric;received numeric;installed numeric;event_id uuid;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'installation');if exists(select 1 from public.fsux7_installation_events where installation_project_id=i and idempotency_key=idempotency)then select id into event_id from public.fsux7_installation_events where installation_project_id=i and idempotency_key=idempotency;return jsonb_build_object('event_id',event_id,'idempotent',true);end if;planned:=(input->>'planned_line_id')::uuid;qty:=(input->>'quantity')::numeric;select coalesce(sum(rl.quantity),0)into received from public.fsux7_planned_lines pl join public.furnishing_procurement_receipt_lines rl on rl.procurement_line_id=pl.procurement_line_id where pl.id=planned;select coalesce(sum(e.quantity),0)into installed from public.fsux7_installation_events e where e.planned_line_id=planned and e.event_type in('installed','accepted');if qty<=0 or installed+qty>received then raise exception 'INSTALLATION_QUANTITY_EXCEEDED';end if;insert into public.fsux7_installation_events(installation_project_id,planned_line_id,room_id,event_type,quantity,installer_description,evidence_class,evidence,recording_actor,correlation_id,idempotency_key)select i,pl.id,pl.room_id,'installed',qty,input->>'external_actor',input->>'evidence_class',input,a,correlation,idempotency from public.fsux7_planned_lines pl where pl.id=planned and pl.installation_project_id=i returning id into event_id;update public.furnishing_installation_projects set tracking_status='installation_in_progress',current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;return jsonb_build_object('event_id',event_id,'idempotent',false);end$$;
create function public.fsux7_record_shipment(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;oid uuid;olid uuid;qty numeric;ordered numeric;shipped numeric;sid uuid;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'record_shipment');select id into sid from public.furnishing_shipments where installation_project_id=i and idempotency_key=idempotency;if found then return jsonb_build_object('shipment_id',sid,'idempotent',true);end if;oid:=(input->>'order_id')::uuid;olid:=(input->>'order_line_id')::uuid;qty:=(input->>'quantity')::numeric;select ordered_quantity into ordered from public.furnishing_procurement_order_lines where id=olid and order_id=oid for update;if not found then raise exception 'SHIPMENT_ORDER_LINE_INVALID';end if;select coalesce(sum(sl.quantity),0)into shipped from public.furnishing_shipment_lines sl join public.furnishing_shipments s on s.id=sl.shipment_id where sl.order_line_id=olid and s.archived_at is null;if qty<=0 or shipped+qty>ordered then raise exception 'SHIPMENT_QUANTITY_EXCEEDED';end if;insert into public.furnishing_shipments(order_id,carrier,tracking_number,status,installation_project_id,evidence_class,verification_state,correlation_id,idempotency_key)values(oid,nullif(input->>'carrier',''),nullif(input->>'tracking_reference',''),'shipped',i,input->>'evidence_class',case when input->>'evidence_class' in('operator_verified','document_verified','provider_confirmed','controlled_test')then'verified'else'reported_unverified'end,correlation,idempotency)returning id into sid;insert into public.furnishing_shipment_lines(shipment_id,order_line_id,quantity)values(sid,olid,qty);update public.furnishing_installation_projects set current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;return jsonb_build_object('shipment_id',sid,'idempotent',false,'external_effects',false);end$$;
create function public.fsux7_record_delivery(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;sid uuid;eid uuid;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'record_delivery');select id into eid from public.fsux7_delivery_events where installation_project_id=i and idempotency_key=idempotency;if found then return jsonb_build_object('delivery_event_id',eid,'idempotent',true);end if;sid:=(input->>'shipment_id')::uuid;if not exists(select 1 from public.furnishing_shipments where id=sid and installation_project_id=i)then raise exception 'DELIVERY_SHIPMENT_INVALID';end if;insert into public.fsux7_delivery_events(installation_project_id,shipment_id,state,evidence_class,event_at,receiving_person,delivery_location,condition_summary,evidence,recording_actor,correlation_id,idempotency_key)values(i,sid,input->>'state',input->>'evidence_class',coalesce((input->>'event_at')::timestamptz,now()),input->>'external_receiver',input->>'delivery_location',input->>'condition_summary',input,a,correlation,idempotency)returning id into eid;update public.furnishing_installation_projects set current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;return jsonb_build_object('delivery_event_id',eid,'physical_receipt_created',false,'idempotent',false);end$$;
create function public.fsux7_record_room_allocation(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;pl uuid;rl uuid;qty numeric;received numeric;allocated numeric;rid uuid;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'room_allocation');select id into rid from public.fsux7_room_allocations where installation_project_id=i and idempotency_key=idempotency;if found then return jsonb_build_object('allocation_id',rid,'idempotent',true);end if;pl:=(input->>'planned_line_id')::uuid;rl:=(input->>'receipt_line_id')::uuid;qty:=(input->>'quantity')::numeric;select quantity into received from public.furnishing_procurement_receipt_lines where id=rl for update;select coalesce(sum(quantity),0)into allocated from public.fsux7_room_allocations where receipt_line_id=rl and archived_at is null;if qty<=0 or allocated+qty>received then raise exception 'ROOM_ALLOCATION_QUANTITY_EXCEEDED';end if;insert into public.fsux7_room_allocations(installation_project_id,planned_line_id,receipt_line_id,source_room_id,destination_room_id,location,quantity,actor_id,correlation_id,idempotency_key)select i,x.id,rl,x.room_id,coalesce((input->>'room_id')::uuid,x.room_id),coalesce(input->>'location','room'),qty,a,correlation,idempotency from public.fsux7_planned_lines x where x.id=pl and x.installation_project_id=i returning id into rid;if rid is null then raise exception 'ROOM_ALLOCATION_SOURCE_INVALID';end if;update public.furnishing_installation_projects set current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;return jsonb_build_object('allocation_id',rid,'idempotent',false);end$$;
create function public.fsux7_record_inspection(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;x uuid;pl uuid;qty numeric;installed numeric;inspected numeric;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'inspection');select id into x from public.fsux7_inspections where installation_project_id=i and idempotency_key=idempotency;if found then return jsonb_build_object('inspection_id',x,'idempotent',true);end if;pl:=nullif(input->>'planned_line_id','')::uuid;qty:=nullif(input->>'quantity','')::numeric;if pl is not null then select coalesce(sum(quantity),0)into installed from public.fsux7_installation_events where planned_line_id=pl and event_type in('installed','accepted')and archived_at is null;select coalesce(sum(quantity),0)into inspected from public.fsux7_inspections where planned_line_id=pl and result in('passed','accepted_with_warnings')and archived_at is null;if qty is null or inspected+qty>installed then raise exception 'INSPECTION_QUANTITY_EXCEEDED';end if;end if;insert into public.fsux7_inspections(installation_project_id,room_id,inspection_type,template_version,result,checks,evidence,external_inspector,recording_actor,correlation_id,idempotency_key,planned_line_id,quantity)values(i,nullif(input->>'room_id','')::uuid,input->>'inspection_type',coalesce(input->>'template_version','fs-ux-007-v1'),input->>'result',coalesce(input->'checks','{}'),coalesce(input->'evidence','{}'),input->>'external_inspector',a,correlation,idempotency,pl,qty)returning id into x;update public.furnishing_installation_projects set tracking_status=case when input->>'inspection_type'='property'then'awaiting_inspection'else tracking_status end,current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;return jsonb_build_object('inspection_id',x,'idempotent',false);end$$;
create function public.fsux7_approve_completion(i uuid,expected bigint,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;s jsonb;sid uuid;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found then raise exception 'INSTALLATION_TRACKING_NOT_FOUND';end if;a:=public.fsux7_assert_action(i,'approve_completion');select id into sid from public.fsux7_completion_snapshots where installation_project_id=i and idempotency_key=idempotency;if found then return jsonb_build_object('snapshot_id',sid,'idempotent',true);end if;if p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;if exists(select 1 from public.fsux7_planned_lines pl where pl.installation_project_id=i and pl.fulfillment_required and((select coalesce(sum(rl.quantity),0)from public.furnishing_procurement_receipt_lines rl where rl.procurement_line_id=pl.procurement_line_id)<pl.planned_quantity or(select coalesce(sum(e.quantity),0)from public.fsux7_installation_events e where e.planned_line_id=pl.id and e.event_type in('installed','accepted'))<pl.planned_quantity))or exists(select 1 from public.fsux7_tracking_exceptions e where e.installation_project_id=i and e.status='open' and e.severity='blocking')or not exists(select 1 from public.fsux7_inspections x where x.installation_project_id=i and x.inspection_type='property' and x.result in('passed','accepted_with_warnings'))then raise exception 'INSTALLATION_COMPLETION_BLOCKED';end if;s:=jsonb_build_object('schemaVersion','fs-ux-007-v1','project',to_jsonb(p),'sourceReadinessSnapshotId',p.source_readiness_snapshot_id,'plannedLines',(select jsonb_agg(to_jsonb(x)order by x.id)from public.fsux7_planned_lines x where x.installation_project_id=i),'orders',(select jsonb_agg(to_jsonb(x)order by x.created_at)from public.fsux7_order_evidence x where x.installation_project_id=i),'deliveries',(select jsonb_agg(to_jsonb(x)order by x.event_at)from public.fsux7_delivery_events x where x.installation_project_id=i),'installations',(select jsonb_agg(to_jsonb(x)order by x.created_at)from public.fsux7_installation_events x where x.installation_project_id=i),'exceptions',(select jsonb_agg(to_jsonb(x)order by x.created_at)from public.fsux7_tracking_exceptions x where x.installation_project_id=i),'inspections',(select jsonb_agg(to_jsonb(x)order by x.created_at)from public.fsux7_inspections x where x.installation_project_id=i));insert into public.fsux7_completion_snapshots(installation_project_id,tracking_version,snapshot,snapshot_digest,approved_by,correlation_id,idempotency_key)values(i,expected,s,encode(digest(s::text,'sha256'),'hex'),a,correlation,idempotency)returning id into sid;update public.furnishing_installation_projects set tracking_status='complete',status='closed',completed_by=a,completed_at=now(),current_tracking_version=current_tracking_version+1 where id=i;return jsonb_build_object('snapshot_id',sid,'idempotent',false,'external_effects',false);end$$;
create function public.fsux7_correct_evidence(i uuid,expected bigint,input jsonb,idempotency text,correlation text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.furnishing_installation_projects;a uuid;c uuid;material boolean;original jsonb;source_kind text;begin select * into p from public.furnishing_installation_projects where id=i for update;if not found or p.current_tracking_version<>expected then raise exception 'INSTALLATION_TRACKING_STALE';end if;a:=public.fsux7_assert_action(i,'correct_evidence');select id into c from public.fsux7_evidence_corrections where installation_project_id=i and idempotency_key=idempotency;if found then return jsonb_build_object('correction_id',c,'idempotent',true);end if;material:=coalesce((input->>'material')::boolean,false);if not material and((input->'corrected_evidence')?'quantity'or(input->'corrected_evidence')?'state'or(input->'corrected_evidence')?'result')then raise exception 'NON_MATERIAL_CORRECTION_TRUTH_CHANGE';end if;source_kind:=input->>'source_type';if source_kind='order_evidence'then select to_jsonb(x)into original from public.fsux7_order_evidence x where x.id=(input->>'source_id')::uuid and x.installation_project_id=i;elsif source_kind='delivery_event'then select to_jsonb(x)into original from public.fsux7_delivery_events x where x.id=(input->>'source_id')::uuid and x.installation_project_id=i;elsif source_kind='installation_event'then select to_jsonb(x)into original from public.fsux7_installation_events x where x.id=(input->>'source_id')::uuid and x.installation_project_id=i;elsif source_kind='inspection'then select to_jsonb(x)into original from public.fsux7_inspections x where x.id=(input->>'source_id')::uuid and x.installation_project_id=i;else raise exception 'CORRECTION_SOURCE_INVALID';end if;if original is null then raise exception 'CORRECTION_SOURCE_INVALID';end if;insert into public.fsux7_evidence_corrections(installation_project_id,source_type,source_id,original_evidence,corrected_evidence,reason,material,actor_id,correlation_id,idempotency_key)values(i,source_kind,(input->>'source_id')::uuid,original,input->'corrected_evidence',input->>'reason',material,a,correlation,idempotency)returning id into c;if material then insert into public.fsux7_completion_supersessions(installation_project_id,completion_snapshot_id,correction_id)select i,s.id,c from public.fsux7_completion_snapshots s where s.installation_project_id=i and not exists(select 1 from public.fsux7_completion_supersessions x where x.completion_snapshot_id=s.id);update public.fsux7_inspections set archived_at=now()where installation_project_id=i and archived_at is null;update public.furnishing_installation_projects set tracking_status='awaiting_inspection',status='launch_review',completed_by=null,completed_at=null,current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;else update public.furnishing_installation_projects set current_tracking_version=current_tracking_version+1,updated_at=now()where id=i;end if;return jsonb_build_object('correction_id',c,'material',material,'reapproval_required',material,'idempotent',false);end$$;
create function public.fsux7_immutable()returns trigger language plpgsql set search_path=public,pg_temp as $$begin raise exception 'INSTALLATION_EVIDENCE_IMMUTABLE';end$$;
create function public.fsux7_completion_guard()returns trigger language plpgsql set search_path=public,pg_temp as $$begin if exists(select 1 from public.fsux7_planned_lines p where p.installation_project_id=new.installation_project_id and p.fulfillment_required and(select coalesce(sum(i.quantity),0)from public.fsux7_inspections i where i.planned_line_id=p.id and i.result in('passed','accepted_with_warnings')and i.archived_at is null)<p.planned_quantity)then raise exception 'INSTALLATION_INSPECTION_INCOMPLETE';end if;return new;end$$;
create trigger fsux7_planned_immutable before update or delete on public.fsux7_planned_lines for each row execute function public.fsux7_immutable();create trigger fsux7_completion_immutable before update or delete on public.fsux7_completion_snapshots for each row execute function public.fsux7_immutable();
create trigger fsux7_completion_guard before insert on public.fsux7_completion_snapshots for each row execute function public.fsux7_completion_guard();
create trigger fsux7_correction_immutable before update or delete on public.fsux7_evidence_corrections for each row execute function public.fsux7_immutable();create trigger fsux7_supersession_immutable before update or delete on public.fsux7_completion_supersessions for each row execute function public.fsux7_immutable();
create trigger fsux7_order_evidence_project_open before insert or update on public.fsux7_order_evidence for each row execute function public.fsux7_guard_project_open();
create trigger fsux7_delivery_project_open before insert or update on public.fsux7_delivery_events for each row execute function public.fsux7_guard_project_open();
create trigger fsux7_unit_project_open before insert or update on public.fsux7_inventory_units for each row execute function public.fsux7_guard_project_open();
create trigger fsux7_room_allocation_project_open before insert or update on public.fsux7_room_allocations for each row execute function public.fsux7_guard_project_open();
create trigger fsux7_installation_project_open before insert or update on public.fsux7_installation_events for each row execute function public.fsux7_guard_project_open();
create trigger fsux7_exception_project_open before insert or update on public.fsux7_tracking_exceptions for each row execute function public.fsux7_guard_project_open();
create trigger fsux7_return_project_open before insert or update on public.fsux7_return_replacement_evidence for each row execute function public.fsux7_guard_project_open();
create trigger fsux7_inspection_project_open before insert or update on public.fsux7_inspections for each row execute function public.fsux7_guard_project_open();
