create table public.fsux7_cleanup_manifests(id uuid primary key default gen_random_uuid(),designation_id uuid not null unique references public.furnishing_controlled_fixture_designations(id),project_id uuid not null references public.furnishing_projects(id),installation_project_id uuid not null references public.furnishing_installation_projects(id),manifest jsonb not null,cleanup_run_id uuid references public.furnishing_cleanup_runs(id),created_at timestamptz not null default now());
create or replace function public.assert_fs008g_cleanup_dependencies(p_designation_id uuid,p_lock boolean default false)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare d public.furnishing_controlled_fixture_designations%rowtype;begin select * into d from public.furnishing_controlled_fixture_designations where id=p_designation_id;if not found or d.project_id is null then raise exception 'CLEANUP_DESIGNATION_INVALID';end if;if p_lock then perform 1 from public.furnishing_plans where project_id=d.project_id for update;perform 1 from public.furnishing_budgets where project_id=d.project_id for update;perform 1 from public.furnishing_procurement_items where project_id=d.project_id for update;perform 1 from public.fs008d_project_catalog_snapshots where project_id=d.project_id for update;perform 1 from public.fs008d_snapshot_items where project_id=d.project_id for update;perform 1 from public.furnishing_procurement_baselines where project_id=d.project_id for update;perform 1 from public.furnishing_project_procurement_budgets where project_id=d.project_id for update;perform 1 from public.furnishing_procurement_orders where project_id=d.project_id for update;perform 1 from public.furnishing_installation_projects where project_id=d.project_id for update;perform 1 from public.notifications where workspace_id=d.workspace_id and(subject_id=d.project_id::text or action_url like'%'||d.project_id::text||'%')for update;perform 1 from public.commerce_payments where workspace_id=d.workspace_id for update;end if;if exists(select 1 from public.customer_accounts where tenant_id=d.workspace_id and id is distinct from d.controlled_customer_account_id)or not exists(select 1 from public.customer_accounts where id=d.controlled_customer_account_id and tenant_id=d.workspace_id)or exists(select 1 from public.integration_connections where workspace_id=d.workspace_id)then raise exception 'CLEANUP_CUSTOMER_OR_PROVIDER_DEPENDENCY';end if;if exists(select 1 from public.notifications where workspace_id=d.workspace_id and(subject_id=d.project_id::text or action_url like'%'||d.project_id::text||'%'))then raise exception 'CLEANUP_NOTIFICATION_DEPENDENCY';end if;if exists(select 1 from public.commerce_payments where workspace_id=d.workspace_id)then raise exception 'CLEANUP_PAYMENT_DEPENDENCY';end if;if exists(select 1 from public.furnishing_procurement_orders where project_id=d.project_id and archived_at is null and(external_order_id is not null or status in('ordered','partially_fulfilled','shipped','delivered','returned','refunded')))then raise exception 'CLEANUP_RETAILER_ORDER_DEPENDENCY';end if;if exists(select 1 from public.furnishing_installation_projects where project_id=d.project_id and archived_at is null)or exists(select 1 from public.furnishing_installation_tasks where project_id=d.project_id and status not in('pending','cancelled','not_required'))then raise exception 'CLEANUP_INSTALLATION_DEPENDENCY';end if;if exists(select 1 from public.furnishing_procurement_items where project_id=d.project_id and status<>'not_ordered')or exists(select 1 from public.furnishing_procurement_exceptions e join public.furnishing_procurement_baselines b on b.id=e.baseline_id where b.project_id=d.project_id and e.status<>'resolved')then raise exception 'CLEANUP_NON_CONTROLLED_PROCUREMENT_DEPENDENCY';end if;if exists(select 1 from public.furnishing_plans where project_id=d.project_id and created_at<d.created_at)or exists(select 1 from public.furnishing_budgets where project_id=d.project_id and created_at<d.created_at)or exists(select 1 from public.fs008d_project_catalog_snapshots where project_id=d.project_id and created_at<d.created_at)then raise exception 'CLEANUP_NON_CONTROLLED_LIFECYCLE_DEPENDENCY';end if;end$$;
alter function public.cleanup_fs008g_synthetic_project(jsonb) rename to cleanup_fs008g_synthetic_project_pre_fsux7;
create function public.cleanup_fs008g_synthetic_project(p_input jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare designation uuid;project uuid;installation uuid;prior public.fsux7_cleanup_manifests;counts jsonb;predecessor jsonb;run_id uuid;begin if auth.role()<>'service_role'then raise exception 'FS008G_FIXTURE_SERVICE_ROLE_REQUIRED' using errcode='42501';end if;begin designation:=(p_input->>'designation_id')::uuid;project:=(p_input->>'project_id')::uuid;exception when others then raise exception 'CLEANUP_COMMAND_INVALID';end;select * into prior from public.fsux7_cleanup_manifests where designation_id=designation;if found then return jsonb_build_object('status','already_cleaned','id',prior.cleanup_run_id,'reconciliation',prior.manifest);end if;select id into installation from public.furnishing_installation_projects where project_id=project and archived_at is null for update;if installation is null then predecessor:=public.cleanup_fs008g_synthetic_project_pre_fsux7(p_input);return predecessor;end if;perform 1 from public.furnishing_controlled_fixture_designations d where d.id=designation and d.project_id=project and d.cleaned_at is null and d.revoked_at is null and d.expires_at>now() for update;if not found then raise exception 'CLEANUP_DESIGNATION_INVALID';end if;perform 1 from public.fsux7_order_evidence where installation_project_id=installation and archived_at is null for update;perform 1 from public.fsux7_delivery_events where installation_project_id=installation and archived_at is null for update;perform 1 from public.fsux7_installation_events where installation_project_id=installation and archived_at is null for update;if exists(select 1 from public.fsux7_order_evidence where installation_project_id=installation and evidence_class<>'controlled_test' and archived_at is null)or exists(select 1 from public.fsux7_delivery_events where installation_project_id=installation and evidence_class<>'controlled_test' and archived_at is null)or exists(select 1 from public.fsux7_installation_events where installation_project_id=installation and evidence_class<>'controlled_test' and archived_at is null)then raise exception 'CLEANUP_EXTERNAL_EVIDENCE_PROHIBITED';end if;select jsonb_build_object('orders',(select count(*)from public.fsux7_order_evidence where installation_project_id=installation and archived_at is null),'allocations',(select count(*)from public.fsux7_order_allocations a join public.fsux7_order_evidence e on e.id=a.order_evidence_id where e.installation_project_id=installation and a.archived_at is null),'deliveries',(select count(*)from public.fsux7_delivery_events where installation_project_id=installation and archived_at is null),'roomAllocations',(select count(*)from public.fsux7_room_allocations where installation_project_id=installation and archived_at is null),'installationEvents',(select count(*)from public.fsux7_installation_events where installation_project_id=installation and archived_at is null),'exceptions',(select count(*)from public.fsux7_tracking_exceptions where installation_project_id=installation and archived_at is null),'inspections',(select count(*)from public.fsux7_inspections where installation_project_id=installation and archived_at is null),'retainedCorrections',(select count(*)from public.fsux7_evidence_corrections where installation_project_id=installation),'retainedCompletionSnapshots',(select count(*)from public.fsux7_completion_snapshots where installation_project_id=installation))into counts;update public.fsux7_order_allocations set archived_at=now()where order_evidence_id in(select id from public.fsux7_order_evidence where installation_project_id=installation)and archived_at is null;update public.fsux7_order_evidence set archived_at=now()where installation_project_id=installation and archived_at is null;update public.fsux7_delivery_events set archived_at=now()where installation_project_id=installation and archived_at is null;update public.fsux7_inventory_units set archived_at=now()where installation_project_id=installation and archived_at is null;update public.fsux7_room_allocations set archived_at=now()where installation_project_id=installation and archived_at is null;update public.fsux7_installation_events set archived_at=now()where installation_project_id=installation and archived_at is null;update public.fsux7_tracking_exceptions set archived_at=now()where installation_project_id=installation and archived_at is null;update public.fsux7_return_replacement_evidence set archived_at=now()where installation_project_id=installation and archived_at is null;update public.fsux7_inspections set archived_at=now()where installation_project_id=installation and archived_at is null;update public.furnishing_installation_projects set tracking_status='archived',archived_at=now()where id=installation;update public.furnishing_shipments set archived_at=now()where installation_project_id=installation and evidence_class='controlled_test' and archived_at is null;update public.furnishing_procurement_receipts set archived_at=now()where installation_project_id=installation and evidence_class='controlled_test' and archived_at is null;update public.furnishing_procurement_orders set archived_at=now()where installation_project_id=installation and evidence_class='controlled_test' and archived_at is null;perform public.assert_fs008g_cleanup_dependencies(designation,true);predecessor:=public.cleanup_fs008g_synthetic_project_pre_fsux7(p_input);run_id:=(predecessor->>'id')::uuid;insert into public.fsux7_cleanup_manifests(designation_id,project_id,installation_project_id,manifest,cleanup_run_id)values(designation,project,installation,(predecessor->'reconciliation')||jsonb_build_object('fsux7',counts),run_id)returning * into prior;return jsonb_build_object('status','clean','id',run_id,'reconciliation',prior.manifest);end$$;
do $$declare t text;begin foreach t in array array['fsux7_planned_lines','fsux7_order_evidence','fsux7_delivery_events','fsux7_inventory_units','fsux7_room_allocations','fsux7_installation_events','fsux7_tracking_exceptions','fsux7_return_replacement_evidence','fsux7_inspections','fsux7_evidence_corrections','fsux7_completion_snapshots','fsux7_completion_supersessions','fsux7_project_assignments']loop execute format('alter table public.%I enable row level security',t);execute format('create policy "Members read %s" on public.%I for select to authenticated using(exists(select 1 from public.furnishing_installation_projects p where p.id=installation_project_id and(public.active_workspace_role(p.workspace_id)is not null or public.is_admin())))',t,t);end loop;end$$;
alter table public.fsux7_order_allocations enable row level security;
create policy "Members read fsux7_order_allocations" on public.fsux7_order_allocations for select to authenticated using(exists(select 1 from public.fsux7_order_evidence e join public.furnishing_installation_projects p on p.id=e.installation_project_id where e.id=order_evidence_id and(public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
revoke all on public.fsux7_planned_lines,public.fsux7_order_evidence,public.fsux7_order_allocations,public.fsux7_delivery_events,public.fsux7_inventory_units,public.fsux7_room_allocations,public.fsux7_installation_events,public.fsux7_tracking_exceptions,public.fsux7_return_replacement_evidence,public.fsux7_inspections,public.fsux7_evidence_corrections,public.fsux7_completion_snapshots,public.fsux7_completion_supersessions,public.fsux7_project_assignments from public,anon,authenticated;grant select on public.fsux7_planned_lines,public.fsux7_order_evidence,public.fsux7_order_allocations,public.fsux7_delivery_events,public.fsux7_inventory_units,public.fsux7_room_allocations,public.fsux7_installation_events,public.fsux7_tracking_exceptions,public.fsux7_return_replacement_evidence,public.fsux7_inspections,public.fsux7_evidence_corrections,public.fsux7_completion_snapshots,public.fsux7_completion_supersessions,public.fsux7_project_assignments to authenticated;
alter table public.fsux7_cleanup_manifests enable row level security;create policy "Admins read fsux7 cleanup manifests" on public.fsux7_cleanup_manifests for select to authenticated using(public.is_admin()and exists(select 1 from public.furnishing_projects p where p.id=project_id and public.active_workspace_role(p.workspace_id)is not null));revoke all on public.fsux7_cleanup_manifests from public,anon,authenticated;grant select on public.fsux7_cleanup_manifests to authenticated;
revoke all on function public.fsux7_assert_actor(uuid,boolean),public.fsux7_assert_action(uuid,text),public.fsux7_guard_project_open(),public.fsux7_immutable(),public.fsux7_completion_guard(),public.fsux7_create_project(uuid,text,text),public.fsux7_record_order(uuid,bigint,jsonb,text,text),public.fsux7_record_shipment(uuid,bigint,jsonb,text,text),public.fsux7_record_delivery(uuid,bigint,jsonb,text,text),public.fsux7_record_receipt(uuid,bigint,jsonb,text,text),public.fsux7_record_room_allocation(uuid,bigint,jsonb,text,text),public.fsux7_record_installation(uuid,bigint,jsonb,text,text),public.fsux7_record_inspection(uuid,bigint,jsonb,text,text),public.fsux7_correct_evidence(uuid,bigint,jsonb,text,text),public.fsux7_approve_completion(uuid,bigint,text,text),public.cleanup_fs008g_synthetic_project(jsonb),public.cleanup_fs008g_synthetic_project_pre_fsux7(jsonb)from public,anon,authenticated;grant execute on function public.fsux7_create_project(uuid,text,text),public.fsux7_record_order(uuid,bigint,jsonb,text,text),public.fsux7_record_shipment(uuid,bigint,jsonb,text,text),public.fsux7_record_delivery(uuid,bigint,jsonb,text,text),public.fsux7_record_receipt(uuid,bigint,jsonb,text,text),public.fsux7_record_room_allocation(uuid,bigint,jsonb,text,text),public.fsux7_record_installation(uuid,bigint,jsonb,text,text),public.fsux7_record_inspection(uuid,bigint,jsonb,text,text),public.fsux7_correct_evidence(uuid,bigint,jsonb,text,text),public.fsux7_approve_completion(uuid,bigint,text,text)to authenticated;grant execute on function public.cleanup_fs008g_synthetic_project(jsonb),public.cleanup_fs008g_synthetic_project_pre_fsux7(jsonb)to service_role;
commit;
